<template>
	<view class="container">
		<u-loading-page :loading="true" v-if="load" fontSize="28rpx" />
		<block v-else>
		<view class="search-top">
			<u-search
			bgColor="#F1F3F5"
			placeholder="请输入搜索关键词" 
			@search="search"
			@custom="search"
			v-model="keyword" />
		</view>
		<view class="sort-items">
			<view class="sort-item" @click="changeShowPopup" :class="{'active':num==1}">
				<text>{{firstStr}}</text>
				<image src="@/static/common/ic_down_24dp.png" mode="widthFix" class="sort-icon"/>
			</view>
			<view class="sort-item" @click="changeSalesSum" :class="{'active':num==2}">
				<text>销量</text>
			</view>
			<view class="sort-item" @click="changeGoodsPrice" :class="{'active':num==3}">
				<text>价格</text>
				<image src="@/static/common/ic_up_24dp.png" mode="widthFix" class="sort-icon" v-if="num==3 && sort=='asc'"/>
				<image src="@/static/common/ic_down_24dp.png" mode="widthFix" class="sort-icon" v-else-if="num==3 && sort=='desc'"/>
				<image src="@/static/common/ic_down_24dp.png" mode="widthFix" class="sort-icon" v-else/>
			</view>
			<view class="sort-last" @click="changeList">
				<image :src="listClick==1?'/static/common/icon_liebiao.png':'/static/common/icon_fenlei.png'" mode="widthFix" class="sort-icon"/>
			</view>
			<view class="sort-popup" v-if="showPopup">
				<view class="sort-popup-item" :class="{'active':zongheStr1==''}" @click="changeZongHe('')">
					<text>综合</text>
					<image src="@/static/common/duihao.png" v-if="zongheStr1==''" mode="widthFix" class="sort-popup-icon"/>
				</view>
				<view class="sort-popup-item" :class="{'active':zongheStr1=='goods_id'}" @click="changeZongHe('goods_id')">
					<text>新品</text>
					<image src="@/static/common/duihao.png" v-if="zongheStr1=='goods_id'" mode="widthFix" class="sort-popup-icon"/>
				</view>
				<view class="sort-popup-item" :class="{'active':zongheStr1=='comment_count'}" @click="changeZongHe('comment_count')" v-if="false">
					<text>评价</text>
					<image src="@/static/common/duihao.png" v-if="zongheStr1=='comment_count'" mode="widthFix" class="sort-popup-icon"/>
				</view>
			</view>
		</view>
		<scroll-view scroll-y="true" class="scroll" @scrolltolower="loadMore">
			<view class="goods" v-if="lists.length>0">
				<view class="goods-item-rows" v-if="listClick==1">
					<view class="goods-item-row" v-for="(item,index) in lists" :key="index" @click="toNext(`/pages/index/goods-detail?goods_id=${item.goods_id}`)">
						<image :src="item.goods_img" class="goods-img" mode="aspectFit"/>
						<view class="goods-right">
							<view class="goods-name">{{item.goods_name}}</view>
							<view class="goods-center">
								<view class="goods-price">
									<text>¥</text>
									<text class="jiage">{{item.goods_price}}</text>
								</view>
								<image src="@/static/common/join-cart.png" mode="widthFix" class="cart-img" @click.stop="join_cart(item)"></image>
							</view>
							<view class="goods-bot" v-if="false">
								<text class="market-price">¥{{item.market_price}}</text>
							</view>
						</view>
					</view>
				</view>
				<view class="goods-items" v-else>
					<view class="goods-item" v-for="(item,index) in lists" :key="item.goods_id" @click="goNext(`/pages/index/goods-detail?goods_id=${item.goods_id}`)">
						<video
						:id="`video${item.goods_id}`"
						:src="getFullUrl(item.video)" 
						:controls="false" 
						:muted="false"
						class="goods-video"
						:poster="getFullUrl(item.goods_img)"
						@click.stop=""
						@play="videoPlay(item.goods_id)"
						v-if="item.video"></video>
						<image :src="item.goods_img" mode="aspectFill" class="goods-img" v-else/>
						<view class="goods-name">{{item.goods_name}}</view>
						<view class="goods-price">
							<view class="price-left">
								<text class="fuhao">¥</text>
								<text class="jiage">{{item.goods_price}}</text>
							</view>
							<image src="@/static/common/join-cart.png" mode="widthFix" class="cart-img" @click.stop="join_cart(item)"></image>
						</view>
					</view>
				</view>
				<u-loadmore class="load-more" :status="hasMore?'loading':'nomore'" :nomoreText="noMore" />
			</view>
			<view class="empty-container" v-else>
				<u-empty text="暂无相关商品" :icon="emptyIcon" />
			</view>
		</scroll-view>
		</block>
	</view>
</template>

<script>
	var _this;
	export default {
		data() {
			return {
				page:1,
				pageNum:10,
				store_id:0,
				cate_id:0,
				is_tj:0,
				goods_type:0,
				sort: 'asc',
				keyword: '',
				zongheStr: '',
				zongheStr1: '',
				showPopup:false,
				listClick:1,
				num:0,
				is_yhq:0,
				playId:''
			};
		},
		methods: {
			videoPlay(id){
				if (this.playId != '') {
					let videoContext = uni.createVideoContext(`video${_this.playId}`)
					videoContext.pause()
				}
				_this.playId = id
			},
			search(value){
				// if(_this.keyword==''){
				// 	this.$u.toast('请输入商品名称搜索~')
				// 	return
				// }
				_this.page = 1
				_this.lists = []
				_this.sousuo_goods()
			},
			loadMore(){
				if(_this.hasMore){
					_this.page++
					_this.sousuo_goods()
				}
			},
			async sousuo_goods(){
				const params = {
					pageIndex:_this.page,
					pageSize:_this.pageNum,
					cate_id:_this.cate_id,
					sort:_this.zongheStr,
					sortStr:_this.sort,
					keyword:_this.keyword,
					is_yhq:_this.is_yhq,
				}
				const data = await _this.$post('port/goods_search_list',params)
				_this.lists.push(...data.result.list)
				_this.hasMore=data.result.list.length>=_this.pageNum
				if (_this.load) {
					_this.load = false
				}
			},
			changeList(){
				_this.listClick=_this.listClick==1?2:1
			},
			changeShowPopup(){
				_this.showPopup=!_this.showPopup
				_this.num = 1
			},
			changeZongHe(str){
				if(_this.zongheStr==str){
					return
				}
				_this.zongheStr=str
				_this.zongheStr1=str
				_this.showPopup=false
				_this.page = 1
				_this.lists = []
				_this.sousuo_goods()
			},
			//点击销量
			changeSalesSum(){
				if(_this.num==2){
					return
				}
				_this.num=2
				_this.zongheStr='sales_sum'
				_this.page = 1
				_this.lists = []
				_this.sousuo_goods()
			},
			//点击价格
			changeGoodsPrice(){
				if(_this.num==3){
					_this.sort=_this.sort=='asc'?'desc':'asc'
					_this.page = 1
					_this.lists = []
					_this.sousuo_goods()
					return
				}
				_this.num=3
				_this.zongheStr='goods_price'
				_this.sort='asc'
				_this.page = 1
				_this.lists = []
				_this.sousuo_goods()
			},
			//加入购物车
			async join_cart(item){
				const params = {
					goods_id: item.goods_id,
					goods_num: 1,
				}
				const data = await _this.$post('port/add_cart', params)
				if(data.code==200){
					this.$u.toast(data.msg)
				}else{
					this.$u.toast(data.msg)
				}
			},
		},
		onLoad(e) {
			_this = this;
			if (e.keyword) {
				_this.keyword=e.keyword
			}
			if (e.goods_type) {
				_this.goods_type=e.goods_type
			}
			if (e.cate_id) {
				_this.cate_id = e.cate_id
			}
			if (e.is_yhq) {
				_this.is_yhq = e.is_yhq
			}
			_this.sousuo_goods()
		},
		onShow() {

		},
		components: {},
		computed:{
			firstStr:{
				cache:false,
				get() {
					if(this.zongheStr1==''){
						return '综合'
					}else if(this.zongheStr1=='goods_id'){
						return '新品'
					}else{
						return '评价'
					}
				}
			}
		},
	}
</script>

<style lang="scss" scoped>
	@import "static/css/goods.scss";
	.container {
		height: 100%;
		overflow: hidden;
		.search-top {
			background: #fff;
			padding: 20rpx;
			@include flex-box(row,null,center);
		}
		.sort-items{
			height: 90rpx;
			@include flex-box(row,null,center);
			background: #fff;
			position: relative;
			.sort-item{
				flex: 1;
				@include flex-box(row,center,center);
				text{
					color: $text-888;
				}
				.sort-icon{
					width: 40rpx;
				}
			}
			.active{
				text{
					color: $text-theme;
				}
			}
			.sort-last{
				padding: 0 30rpx;
				@include flex-box(row,center,center);
				.sort-icon{
					width: 34rpx;
				}
			}
			.sort-popup{
				z-index: 1;
				position: absolute;
				left: 0;
				top: 90rpx;
				width: 100%;
				background: #fff;
				.sort-popup-item{
					padding: 0 20rpx;
					height: 90rpx;
					@include flex-box(row,space-between,center);
					.sort-popup-icon{
						width: 30rpx;
					}
				}
				.active{
					text{
						color: $text-theme;
					}
				}
			}
		}
		.scroll{
			height: calc(100% - 64rpx - 130rpx);
			.goods{
				.goods-items{
					padding: 20rpx 30rpx 0 30rpx;
